import Image from "next/image";
import { shimmer } from "@/components/utils/shimmer";
import cdnImage from "@/helpers/cdnImage";

const toBase64 = (str: string) =>
  typeof window === "undefined"
    ? Buffer.from(str).toString("base64")
    : window.btoa(str);

export default function GallerySingle({
  images,
  onLightBoxIndexChange,
  tourName,
}: {
  images: any;
  onLightBoxIndexChange: any;
  tourName: any;
}) {
  return (
    <div className="tw-py-4 tw-mb-2">
      <div>
          <Image
            src={cdnImage(images[0].imageUrl)}
            alt={tourName}
            width={1000}
            height={400}
            className="tw-w-full tw-h-auto tw-rounded-xl"
            quality={100}
            onClick={() => onLightBoxIndexChange(0)}
            placeholder={`data:image/svg+xml;base64,${toBase64(
              shimmer(1000, 400)
            )}`}
          />
      </div>
    </div>
  );
}
