import Image from "next/image";
import { shimmer } from "@/components/utils/shimmer";
import cdnImage from "@/helpers/cdnImage";

const toBase64 = (str: string) =>
  typeof window === "undefined"
    ? Buffer.from(str).toString("base64")
    : window.btoa(str);

export default function Gallery({
  images,
  onLightBoxIndexChange,
  tourName,
}: {
  images: any;
  onLightBoxIndexChange: any;
  tourName: any;
}) {
  if (images.length <= 1) return null;

  return (
    <div className="tw-hidden lg:tw-block tw-py-4 tw-mb-2">
      <div className="tw-flex tw-flex-wrap -tw-mx-2">
        <div className="tw-w-1/2 tw-p-2">
          <Image
            src={cdnImage(images[0].imageUrl)}
            alt={tourName + " 1"}
            width={1000}
            height={400}
            className="tw-block tw-w-full tw-rounded-xl"
            style={{ objectFit: "cover", cursor: "pointer" }}
            quality={100}
            onClick={() => onLightBoxIndexChange(0)}
            placeholder={`data:image/svg+xml;base64,${toBase64(
              shimmer(1000, 400)
            )}`}
          />
        </div>
        {images.length == 2 && (
          <>
            <div className="tw-w-1/2 tw-p-2">
              <Image
                src={cdnImage(images[1].imageUrl)}
                alt={tourName + " 2"}
                width={1000}
                height={400}
                className="tw-block tw-w-full tw-rounded-xl hover-zoom"
                style={{ objectFit: "cover", cursor: "pointer" }}
                quality={100}
                placeholder={`data:image/svg+xml;base64,${toBase64(
                  shimmer(1000, 400)
                )}`}
              />
            </div>
          </>
        )}
        {images.length == 3 && (
          <>
            <div className="tw-w-1/4 tw-p-2">
              <Image
                src={cdnImage(images[1].imageUrl)}
                alt={tourName + " 2"}
                width={400}
                height={400}
                className="tw-block tw-w-full tw-rounded-xl hover-zoom"
                style={{ objectFit: "cover", cursor: "pointer" }}
                quality={100}
                onClick={() => onLightBoxIndexChange(1)}
                placeholder={`data:image/svg+xml;base64,${toBase64(
                  shimmer(400, 400)
                )}`}
              />
            </div>
            <div className="tw-w-1/4 tw-p-1">
              <Image
                src={cdnImage(images[2].imageUrl)}
                alt={tourName + " 3"}
                width={400}
                height={400}
                className="tw-block tw-w-full tw-rounded-xl hover-zoom"
                style={{ objectFit: "cover", cursor: "pointer" }}
                quality={100}
                onClick={() => onLightBoxIndexChange(2)}
                placeholder={`data:image/svg+xml;base64,${toBase64(
                  shimmer(400, 400)
                )}`}
              />
            </div>
          </>
        )}
        {images.length >= 4 && (
          <>
            <div className="tw-w-1/6 tw-p-2">
              <Image
                src={cdnImage(images[1].imageUrl)}
                alt={tourName + " 2"}
                width={400}
                height={400}
                className="tw-block tw-w-full tw-rounded-xl hover-zoom"
                style={{ objectFit: "cover", cursor: "pointer" }}
                quality={100}
                onClick={() => onLightBoxIndexChange(1)}
                placeholder={`data:image/svg+xml;base64,${toBase64(
                  shimmer(400, 400)
                )}`}
              />
            </div>
            <div className="tw-w-1/6 tw-p-2">
              <Image
                src={cdnImage(images[2].imageUrl)}
                alt={tourName + " 3"}
                width={400}
                height={400}
                className="tw-block tw-w-full tw-rounded-xl hover-zoom"
                style={{ objectFit: "cover", cursor: "pointer" }}
                quality={100}
                onClick={() => onLightBoxIndexChange(2)}
                placeholder={`data:image/svg+xml;base64,${toBase64(
                  shimmer(400, 400)
                )}`}
              />
            </div>
            <div
              className="tw-w-1/6 tw-p-2"
              style={{ position: "relative", display: "inline-block" }}
            >
              <Image
                src={cdnImage(images[3].imageUrl)}
                alt={tourName + " 4"}
                width={400}
                height={400}
                className="tw-block tw-w-full tw-rounded-xl hover-zoom"
                style={{ objectFit: "cover", cursor: "pointer" }}
                quality={100}
                onClick={() => onLightBoxIndexChange(3)}
                placeholder={`data:image/svg+xml;base64,${toBase64(
                  shimmer(400, 400)
                )}`}
              />
              <button
                className="tw-inline-flex tw-items-center tw-justify-center tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-rounded-lg tw-p-2 tw-shadow-sm hover:tw-bg-[#faf9fc] tw-cursor-pointer tw-transition-colors"
                style={{
                  position: "absolute",
                  top: "15px",
                  right: "15px",
                }}
                type="button"
                role="button"
                onClick={() => onLightBoxIndexChange(0)}
              >
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  width="22"
                  height="22"
                  fill="currentColor"
                  className="bi bi-images"
                  viewBox="0 0 16 16"
                >
                  <path d="M4.502 9a1.5 1.5 0 1 0 0-3 1.5 1.5 0 0 0 0 3" />
                  <path d="M14.002 13a2 2 0 0 1-2 2h-10a2 2 0 0 1-2-2V5A2 2 0 0 1 2 3a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2v8a2 2 0 0 1-1.998 2M14 2H4a1 1 0 0 0-1 1h9.002a2 2 0 0 1 2 2v7A1 1 0 0 0 15 11V3a1 1 0 0 0-1-1M2.002 4a1 1 0 0 0-1 1v8l2.646-2.354a.5.5 0 0 1 .63-.062l2.66 1.773 3.71-3.71a.5.5 0 0 1 .577-.094l1.777 1.947V5a1 1 0 0 0-1-1z" />
                </svg>
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}
