import { useEffect, useState } from "react";
import { getCookie, hasCookie } from "cookies-next";
import getUserDetail from "@/services/auth/userDetail";
import downloadRequest from "@/services/downloadBrochureService";
import Modal from "./modal";
import {
  inputCls,
  labelCls,
  primaryBtnCls,
  spinnerCls,
  dangerAlertCls,
} from "./ui";

export default function DownloadBrochureModal({
  tourSlug,
  open,
  onClose,
}: {
  tourSlug: string;
  open: boolean;
  onClose: () => void;
}) {
  const [loading, setLoading] = useState(true);
  const [messageSendLoading, setMessageSendLoading] = useState(false);
  const [isActiveUser, setIsActiveUser] = useState(false);
  const [customerName, setCustomerName] = useState("");
  const [customerEmail, setCustomerEmail] = useState("");
  const [showError, setShowError] = useState(false);
  const [errorMessage, setErrorMessage] = useState("");
  const [bodyContent, setBodyContent] = useState("form");

  const fetchUserDetail = async () => {
    const userData = await getUserDetail({ token: getCookie("auth-token") });
    return userData;
  };

  const formSubmit = () => {
    if (customerName == "" || customerEmail == "") {
      setShowError(true);
      setErrorMessage("Please fill in the required fields");
      return;
    }

    setShowError(false);
    setErrorMessage("");
    setMessageSendLoading(true);

    downloadRequest({
      data: {
        slug: tourSlug,
        first_name: customerName,
        email: customerEmail,
        // Varsa apiv3 token'ı: talep login'li kullanıcıya bağlanır.
        token: getCookie("auth-token-v3")?.toString(),
      },
    })
      .then((res) => {
        setMessageSendLoading(false);
        setBodyContent("success");
      })
      .catch((error) => {
        setMessageSendLoading(false);
        setErrorMessage("There is a problem. Please try again later.");
        setShowError(true);
      });
  };

  useEffect(() => {
    if (hasCookie("auth-token")) {
      fetchUserDetail().then((res: any) => {
        setIsActiveUser(true);
        setCustomerName(res.name);
        setCustomerEmail(res.email);
        setLoading(false);
      });
    } else {
      setLoading(false);
    }
  }, []);

  const footer = messageSendLoading ? (
    <button className={primaryBtnCls} type="button" disabled>
      <span className={spinnerCls} aria-hidden="true"></span>
      <span role="status"> Sending...</span>
    </button>
  ) : bodyContent == "form" ? (
    <button
      type="button"
      className={primaryBtnCls}
      onClick={() => {
        formSubmit();
      }}
    >
      Download
    </button>
  ) : null;

  return (
    <Modal
      open={open}
      onClose={onClose}
      title="Download Brochure"
      staticBackdrop
      hideClose={messageSendLoading}
      footer={footer}
    >
      {loading && "Loading..."}
      {!loading &&
        !messageSendLoading &&
        bodyContent == "success" &&
        "We've sent the brochure to " +
          customerEmail +
          ". Please check your inbox!"}
      {!loading && !messageSendLoading && bodyContent == "form" && (
        <>
          <p className="tw-text-[#5d556c] tw-mt-0">
            {isActiveUser && (
              <span>
                After pressing the &quot;Download&quot; button, the tour
                brochure will be sent to your e-mail address as a PDF.
                <br />
                <br />
                <strong>{customerEmail}</strong>
              </span>
            )}
          </p>
          {showError && (
            <div className={dangerAlertCls} role="alert">
              {errorMessage}
            </div>
          )}
          {!isActiveUser && (
            <>
              <p className="tw-text-[#5d556c]">
                Enter your email to get the brochure containing all the
                important information right to your inbox.
              </p>
              <div className="tw-mb-4">
                <label htmlFor="downloadBrochureFormName" className={labelCls}>
                  First Name <span className="tw-text-[#dc3545]"> (*)</span>
                </label>
                <input
                  type="text"
                  className={inputCls}
                  id="downloadBrochureFormName"
                  onChange={(e) => {
                    setCustomerName(e.target.value);
                  }}
                  defaultValue={customerName}
                />
              </div>
              <div className="tw-mb-4">
                <label htmlFor="downloadBrochureFormEmail" className={labelCls}>
                  Email address <span className="tw-text-[#dc3545]"> (*)</span>
                </label>
                <input
                  type="email"
                  className={inputCls}
                  id="downloadBrochureFormEmail"
                  onChange={(e) => {
                    setCustomerEmail(e.target.value);
                  }}
                  defaultValue={customerEmail}
                />
              </div>
            </>
          )}
        </>
      )}
      {messageSendLoading && (
        <div className="tw-text-center tw-py-4">
          <span
            className={`${spinnerCls} tw-text-[#854ec9] tw-h-8 tw-w-8`}
            role="status"
          ></span>
          <p className="tw-mt-3">Please wait.</p>
        </div>
      )}
    </Modal>
  );
}
