import CheckIcon from "../../../public/icons/CheckIcon";

export default function Highlights({ tourData }: { tourData: any }) {
  const highlights = tourData.highlights || [];

  if (highlights.length === 0) return null;

  return (
    <div className="tw-my-4" id="highlights">
      <h2 className="tw-font-display tw-text-[22px] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-pb-2">
        What makes this tour special
      </h2>

      <div className="tw-flex tw-flex-wrap tw-gap-2">
        {highlights.map((item: any) => (
          <span className="tw-p-1" key={item.id}>
            <CheckIcon /> {item.title}
          </span>
        ))}
      </div>
    </div>
  );
}
