import Image from "next/image";
import React from "react";

const Places = ({ tourData }: any) => {
  return (
    <>
      {tourData.attractions.length > 0 && (
        <div className="tw-my-6" id="attractions">
          <h2 className="tw-font-display tw-text-[22px] tw-font-bold tw-tracking-tight tw-text-[#14101c]">
            Attractions
          </h2>
          <div
            className="tw-flex tw-flex-nowrap tw-items-stretch tw-mt-3"
            style={{ overflowX: "auto" }}
          >
            {tourData.attractions.map((item: any) => (
              <div className="tw-w-1/2 md:tw-w-1/4 tw-flex-none tw-p-2" key={item.id}>
                <div className="tw-mx-2 tw-overflow-hidden tw-rounded-xl">
                  <a
                    href={"/attractions/" + item.slug}
                    target="_blank"
                    title={item.name}
                  >
                    {item.media[0] ? (
                      <Image
                        src={item.media[0].thumb.replace(
                          "tsgroup.s3.amazonaws.com",
                          "d2lpxiu1sq3srq.cloudfront.net"
                        )}
                        alt={item.name}
                        width={400}
                        height={300}
                        className="tw-w-full tw-rounded-xl tw-mx-auto"
                        loading="lazy"
                        style={{ height: "auto" }}
                        quality={100}
                      />
                    ) : (
                      ""
                    )}
                  </a>
                  <div className="tw-p-2">
                    <h3 className="tw-text-center tw-text-[15px] tw-font-semibold">
                      <a
                        href={"/attractions/" + item.slug}
                        target="_blank"
                        title={item.name}
                        className="tw-no-underline tw-text-[#14101c]"
                      >
                        {item.name}
                      </a>
                    </h3>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </>
  );
};

export default Places;
