import styles from "./styles.module.scss";

export default function Overview({ tourData }: { tourData: any }) {
  function convertHeadingsToParagraphs(html: string) {
    return html.replace(
      /<h([1-6])[^>]*>([\s\S]*?)<\/h\1>/gi,
      (match, level, content) => `<p class="h${level}">${content}</p>`
    );
  }

  return (
    <div className="tw-my-4" id="overview">
      <h2 className="tw-font-display tw-text-[22px] tw-font-bold tw-tracking-tight tw-text-[#14101c]">
        About this tour
      </h2>
      <div
        className={`tw-mt-4 ${styles["tour-description"]}`}
        dangerouslySetInnerHTML={{
          __html: tourData.description
            ? convertHeadingsToParagraphs(tourData.description)
            : "",
        }}
      ></div>
      {tourData.category.activities.length > 0 && (
        <div className="tw-flex tw-flex-wrap tw-gap-2 tw-mt-2">
          {tourData.category.activities.map((activity: any) => (
            <span
              className="tw-inline-flex tw-items-center tw-rounded-full tw-border tw-border-solid tw-border-[#ebe7f0] tw-bg-white tw-px-3 tw-py-1.5 tw-text-[13px] tw-font-medium tw-text-[#14101c]"
              key={activity.id}
            >
              {activity.name.en}
            </span>
          ))}
        </div>
      )}
    </div>
  );
}
