"use client";
import { useState } from "react";
import Image from "next/image";
import { useTourModals } from "./tour-modals-context";
import { outlineBtnCls } from "./ui";

type Crumb = { name: string };
type Stop = {
  id?: number | null;
  name: string;
  lat?: number | null;
  lng?: number | null;
  parents?: Crumb[];
};

export default function Route({ tourData }: { tourData: any }) {
  const { openMap, openBrochure } = useTourModals();
  // Hide the map preview + "View Map" button if the static map image fails to load.
  const [mapBroken, setMapBroken] = useState(false);

  const showMap = () =>
    openMap({
      routes: tourData.routes,
      minLat: tourData.minLat,
      minLng: tourData.minLng,
      maxLat: tourData.maxLat,
      maxLng: tourData.maxLng,
    });

  // Resolved server-side (names + ancestor breadcrumbs). Older cached payloads
  // only carry `routes`, so fall back to those rather than dropping the list.
  const stops: Stop[] =
    tourData.routeStops?.length > 0
      ? tourData.routeStops
      : (tourData.routes ?? []).map((r: any) => ({ ...r, name: r.name ?? r.slug }));

  const hasMap = !!tourData.map && !mapBroken;
  const pickup = tourData.pickup_location?.name;
  const dropoff = tourData.dropoff_location?.name;
  // Times are only worth showing when pickup and dropoff differ; otherwise the
  // same clock time would be printed twice.
  const timesDiffer =
    tourData.pickupTime && tourData.pickupTime !== tourData.dropoffTime;

  const FlagIcon = () => (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width="18"
      height="18"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      viewBox="0 0 24 24"
      className="tw-shrink-0 tw-mt-0.5 tw-text-[#854ec9]"
    >
      <path
        strokeLinecap="round"
        strokeLinejoin="round"
        d="M5 21V4m0 0c3-1.5 6 1.5 9 0s5 0 5 0v9s-2 1.5-5 0-6-1.5-9 0"
      />
    </svg>
  );

  return (
    <div className="tw-mt-12">
      <h2 className="tw-font-display tw-text-[22px] tw-font-bold tw-tracking-tight tw-text-[#14101c]">
        Route
      </h2>

      {/* The journey list is the substance here, so it gets the width; the map
          preview is a compact side panel that opens the interactive map. */}
      <div
        className={`tw-mt-4 tw-grid tw-overflow-hidden tw-rounded-2xl tw-border tw-border-solid tw-border-[#ebe7f0] tw-bg-white ${
          hasMap ? "lg:tw-grid-cols-[1fr_320px]" : ""
        }`}
      >
        {/* ===== Stop timeline ===== */}
        <div className="tw-flex tw-min-w-0 tw-flex-col tw-p-5">
          {stops.length > 0 && (
            <>
              <div className="tw-mb-3 tw-flex tw-items-baseline tw-justify-between tw-gap-2 tw-border-0 tw-border-b tw-border-solid tw-border-[#ebe7f0] tw-pb-2.5">
                <span className="tw-text-[11px] tw-font-bold tw-uppercase tw-tracking-[0.08em] tw-text-[#8a8398]">
                  Journey
                </span>
                <span className="tw-text-[12px] tw-font-semibold tw-text-[#5d556c]">
                  {stops.length} {stops.length === 1 ? "stop" : "stops"}
                </span>
              </div>

              <ol className="tw-m-0 tw-list-none tw-p-0 lg:tw-max-h-[330px] lg:tw-overflow-y-auto">
                {stops.map((stop, i) => {
                  // Start/End only mean something on a real multi-stop route.
                  const multi = stops.length > 1;
                  const isStart = multi && i === 0;
                  const isEnd = multi && i === stops.length - 1;

                  return (
                    <li
                      key={`${stop.name}-${i}`}
                      className="tw-relative tw-flex tw-items-start tw-gap-3 tw-px-2.5 tw-py-2"
                    >
                      {i < stops.length - 1 && (
                        <span className="tw-absolute tw-left-[25px] tw-top-[38px] tw-bottom-[-4px] tw-w-0.5 tw-bg-[#e6e0ef]" />
                      )}
                      <span
                        className={`tw-z-[1] tw-inline-flex tw-h-7 tw-w-7 tw-shrink-0 tw-items-center tw-justify-center tw-rounded-full tw-text-[12px] tw-font-bold tw-text-white tw-shadow-[0_0_0_3px_#fff] ${
                          isStart
                            ? "tw-bg-[#1a7a4a]"
                            : isEnd
                              ? "tw-bg-[#d23254]"
                              : "tw-bg-[#854ec9]"
                        }`}
                      >
                        {i + 1}
                      </span>
                      <span className="tw-flex tw-min-w-0 tw-flex-col tw-gap-1 tw-pt-1">
                        <span className="tw-text-[14px] tw-font-semibold tw-leading-tight tw-text-[#14101c]">
                          {stop.name}
                        </span>
                        {/* Where this place sits in the world: Europe › Turkey › Aydin */}
                        {stop.parents && stop.parents.length > 0 && (
                          <span className="tw-flex tw-flex-wrap tw-items-center tw-gap-1 tw-text-[11px] tw-leading-tight tw-text-[#8a8398]">
                            {stop.parents.map((crumb, c) => (
                              <span key={`${crumb.name}-${c}`}>
                                {c > 0 && (
                                  <span aria-hidden="true" className="tw-mr-1">
                                    ›
                                  </span>
                                )}
                                {crumb.name}
                              </span>
                            ))}
                          </span>
                        )}
                        {(isStart || isEnd) && (
                          <span className="tw-flex tw-flex-wrap tw-items-center tw-gap-1.5">
                            {isStart && (
                              <span className="tw-rounded-full tw-bg-[#e8f9f0] tw-px-1.5 tw-py-0.5 tw-text-[10px] tw-font-bold tw-uppercase tw-tracking-[0.03em] tw-text-[#1a7a4a]">
                                Start
                              </span>
                            )}
                            {isEnd && (
                              <span className="tw-rounded-full tw-bg-[#fdeaef] tw-px-1.5 tw-py-0.5 tw-text-[10px] tw-font-bold tw-uppercase tw-tracking-[0.03em] tw-text-[#d23254]">
                                End
                              </span>
                            )}
                          </span>
                        )}
                      </span>
                    </li>
                  );
                })}
              </ol>
            </>
          )}
        </div>

        {/* ===== Map preview + hand-over points ===== */}
        {(hasMap || pickup || dropoff) && (
          <aside
            className={`tw-flex tw-flex-col tw-gap-4 tw-p-5 ${
              hasMap
                ? "lg:tw-border-0 lg:tw-border-l lg:tw-border-solid lg:tw-border-[#ebe7f0]"
                : "tw-border-0 tw-border-t tw-border-solid tw-border-[#ebe7f0]"
            }`}
          >
            {/* Static route image; the live Google map only loads on click. */}
            {hasMap && (
              <button
                type="button"
                onClick={showMap}
                aria-label="Open map"
                className="tw-group tw-relative tw-block tw-w-full tw-cursor-pointer tw-overflow-hidden tw-rounded-xl tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-0"
              >
                <Image
                  src={tourData.map.replace("294x105", "750x500")}
                  width={750}
                  height={500}
                  alt="Tour route map"
                  className="tw-block tw-h-[150px] tw-w-full tw-object-cover"
                  loading="lazy"
                  quality={100}
                  onError={() => setMapBroken(true)}
                />
                <span className="tw-absolute tw-inset-0 tw-flex tw-items-center tw-justify-center">
                  <span className="tw-inline-flex tw-items-center tw-gap-2 tw-rounded-full tw-bg-white tw-px-3.5 tw-py-2 tw-text-[14px] tw-font-semibold tw-text-[#14101c] tw-shadow-md tw-transition group-hover:tw-shadow-lg">
                    <svg
                      xmlns="http://www.w3.org/2000/svg"
                      width="18"
                      height="18"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="1.8"
                      viewBox="0 0 24 24"
                      className="tw-text-[#854ec9]"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        d="M9 3 3 6v15l6-3 6 3 6-3V3l-6 3-6-3z"
                      />
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        d="M9 3v15"
                      />
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        d="M15 6v15"
                      />
                    </svg>
                    View Map
                  </span>
                </span>
              </button>
            )}

            {/* Where the tour physically picks you up / drops you off — often an
                airport, i.e. not one of the journey stops. */}
            {(pickup || dropoff) && (
              <div className="tw-grid tw-gap-3 sm:tw-grid-cols-2 lg:tw-grid-cols-1">
                {pickup && (
                  <div className="tw-flex tw-items-start tw-gap-2.5">
                    <FlagIcon />
                    <span className="tw-min-w-0">
                      <span className="tw-block tw-text-[11px] tw-font-bold tw-uppercase tw-tracking-wide tw-text-[#8a8398]">
                        Pickup Location
                      </span>
                      <span className="tw-block tw-text-[14px] tw-font-medium tw-text-[#14101c]">
                        {pickup}
                        {timesDiffer && <span>, {tourData.pickupTime}</span>}
                      </span>
                    </span>
                  </div>
                )}
                {dropoff && (
                  <div className="tw-flex tw-items-start tw-gap-2.5">
                    <FlagIcon />
                    <span className="tw-min-w-0">
                      <span className="tw-block tw-text-[11px] tw-font-bold tw-uppercase tw-tracking-wide tw-text-[#8a8398]">
                        Dropoff Location
                      </span>
                      <span className="tw-block tw-text-[14px] tw-font-medium tw-text-[#14101c]">
                        {dropoff}
                        {timesDiffer && tourData.dropoffTime && (
                          <span>, {tourData.dropoffTime}</span>
                        )}
                      </span>
                    </span>
                  </div>
                )}
              </div>
            )}
          </aside>
        )}
      </div>

      <div className="lg:tw-hidden tw-mt-4">
        <button
          className={`${outlineBtnCls} tw-w-full`}
          type="button"
          onClick={openBrochure}
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            width="16"
            height="16"
            fill="currentColor"
            viewBox="0 0 16 16"
          >
            <path d="M.5 9.9a.5.5 0 0 1 .5.5v2.5a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-2.5a.5.5 0 0 1 1 0v2.5a2 2 0 0 1-2 2H2a2 2 0 0 1-2-2v-2.5a.5.5 0 0 1 .5-.5" />
            <path d="M7.646 11.854a.5.5 0 0 0 .708 0l3-3a.5.5 0 0 0-.708-.708L8.5 10.293V1.5a.5.5 0 0 0-1 0v8.793L5.354 8.146a.5.5 0 1 0-.708.708z" />
          </svg>{" "}
          Download Brochure
        </button>
      </div>
    </div>
  );
}
