"use client";
import dynamic from "next/dynamic";
import Modal from "./modal";

const Map = dynamic(() => import("./gmaps"), { ssr: false });

export default function MapModal({
  open,
  onClose,
  detail,
}: {
  open: boolean;
  onClose: () => void;
  detail: any;
}) {
  return (
    <Modal open={open} onClose={onClose} title="View Map" size="lg">
      {detail?.routes?.length > 0 && (
        <Map
          tourRoutes={detail.routes}
          maxLat={detail.maxLat}
          minLat={detail.minLat}
          maxLng={detail.maxLng}
          minLng={detail.minLng}
        />
      )}
    </Modal>
  );
}
