import { useEffect, useMemo, useState } from "react";
import { getCookie, hasCookie } from "cookies-next";
import getUserDetail from "@/services/auth/userDetail";
import sendMessage from "@/services/enquiryService";
import ReCAPTCHA from "react-google-recaptcha";
import getLocations from "@/services/locations";
import Select from "react-select";
import Modal from "./modal";
import {
  inputCls,
  labelCls,
  primaryBtnCls,
  spinnerCls,
  dangerAlertCls,
} from "./ui";

// react-select styled to match the modal's rounded, brand-focused fields.
// menuPortal zIndex sits above the modal (z-[1060]).
const phoneSelectStyles = {
  control: (base: any, state: any) => ({
    ...base,
    minHeight: 44,
    borderRadius: 10,
    borderColor: state.isFocused ? "#854ec9" : "#d8d2e1",
    boxShadow: state.isFocused ? "0 0 0 3px rgba(133,78,201,0.15)" : "none",
    "&:hover": { borderColor: state.isFocused ? "#854ec9" : "#cdb6ec" },
    fontSize: 14,
  }),
  valueContainer: (base: any) => ({ ...base, padding: "2px 10px" }),
  menu: (base: any) => ({ ...base, borderRadius: 10, overflow: "hidden" }),
  menuPortal: (base: any) => ({ ...base, zIndex: 100001 }),
  option: (base: any, state: any) => ({
    ...base,
    fontSize: 13.5,
    cursor: "pointer",
    backgroundColor: state.isSelected
      ? "#854ec9"
      : state.isFocused
        ? "#f5f0fc"
        : "#fff",
    color: state.isSelected ? "#fff" : "#14101c",
  }),
};

export default function InquiryModal({
  tourId,
  open,
  onClose,
}: {
  tourId: number;
  open: boolean;
  onClose: () => void;
}) {
  const [loading, setLoading] = useState(true);
  const [messageSendLoading, setMessageSendLoading] = useState(false);
  const [isActiveUser, setIsActiveUser] = useState(false);
  const [customerName, setCustomerName] = useState("");
  const [customerPhoneCodeId, setCustomerPhoneCodeId] = useState<number | null>(
    null
  );
  const [customerPhoneNumber, setCustomerPhoneNumber] = useState<string>("");
  const [customerEmail, setCustomerEmail] = useState("");
  const [googleRecaptcha, setGoogleRecaptcha] = useState<any>(null);
  const [question, setQuestion] = useState("");
  const [showError, setShowError] = useState(false);
  const [errorMessage, setErrorMessage] = useState("");
  const [bodyContent, setBodyContent] = useState("form");
  const [locations, setLocations] = useState<
    Array<{ id: number; name: string; phone_code?: string }>
  >([]);

  const phoneOptions = useMemo(
    () =>
      locations.map((l) => ({
        value: l.id,
        label: `${l.name} (${l.phone_code})`,
      })),
    [locations]
  );

  const fetchUserDetail = async () => {
    const userData = await getUserDetail({ token: getCookie("auth-token") });
    return userData;
  };

  const formSubmit = () => {
    // Validate required fields based on user state
    if (!isActiveUser) {
      if (
        customerName.trim() === "" ||
        customerEmail.trim() === "" ||
        question.trim() === ""
      ) {
        setShowError(true);
        setErrorMessage("Please fill in the required fields.");
        return;
      }
    } else {
      if (question.trim() === "") {
        setShowError(true);
        setErrorMessage("Please fill in the required fields.");
        return;
      }
    }

    if (!isActiveUser && customerPhoneNumber && !customerPhoneCodeId) {
      setShowError(true);
      setErrorMessage("Please select your phone country code.");
      return;
    }

    if (!googleRecaptcha) {
      setShowError(true);
      setErrorMessage("Please confirm robot verification.");
      return;
    }

    setShowError(false);
    setErrorMessage("");
    setMessageSendLoading(true);

    const payload: any = {
      tour_id: tourId,
      "g-recaptcha-response": googleRecaptcha,
      message: question,
    };

    if (!isActiveUser) {
      payload.contact_name = customerName;
      payload.contact_email = customerEmail;

      if (customerPhoneCodeId && customerPhoneNumber) {
        payload.phone_code = customerPhoneCodeId;
        payload.contact_phone = customerPhoneNumber;
      }
    }

    sendMessage({
      data: payload,
    })
      .then((res) => {
        setMessageSendLoading(false);
        setBodyContent("success");
      })
      .catch((error) => {
        setMessageSendLoading(false);

        // Parse API validation errors
        if (error && error.errors && typeof error.errors === "object") {
          const errorMessages = Object.entries(error.errors)
            .map(([field, messages]: [string, any]) => {
              if (Array.isArray(messages)) {
                return messages.join(" ");
              }
              return messages;
            })
            .join(" ");
          setErrorMessage(
            errorMessages || "There is a problem. Please try again later."
          );
        } else if (error && error.message) {
          setErrorMessage(error.message);
        } else {
          setErrorMessage("There is a problem. Please try again later.");
        }

        setShowError(true);
      });
  };

  useEffect(() => {
    // load locations for country codes
    getLocations().then((res) => {
      try {
        const list = Array.isArray(res) ? res : [];
        setLocations(
          list
            .filter((item: any) => item.phone_code && item.phone_code !== "")
            .sort((a: any, b: any) =>
              a.name < b.name ? -1 : a.name > b.name ? 1 : 0
            )
        );
      } catch (e) {
        setLocations([]);
      }
    });

    if (hasCookie("auth-token")) {
      fetchUserDetail().then((res: any) => {
        setIsActiveUser(true);
        setLoading(false);
      });
    } else {
      setLoading(false);
    }
  }, []);

  const footer = messageSendLoading ? (
    <button className={primaryBtnCls} type="button" disabled>
      <span className={spinnerCls} aria-hidden="true"></span>
      <span role="status"> Sending...</span>
    </button>
  ) : bodyContent == "form" ? (
    <button
      type="button"
      className={primaryBtnCls}
      onClick={() => {
        formSubmit();
      }}
    >
      Send Message
    </button>
  ) : null;

  return (
    <Modal
      open={open}
      onClose={onClose}
      title="Ask a Question"
      staticBackdrop
      hideClose={messageSendLoading}
      footer={footer}
    >
      {!loading &&
        !messageSendLoading &&
        bodyContent == "success" &&
        "Your message has been delivered successfully. We will get back to you as soon as possible."}
      {!loading && !messageSendLoading && bodyContent == "form" && (
        <>
          <p className="tw-text-[#5d556c] tw-mt-0">
            {isActiveUser && (
              <span>
                Hello <strong>{customerName}</strong> happy to see you here.
                <br />
              </span>
            )}
            Ask questions to the tour provider.
          </p>
          {showError && (
            <div className={dangerAlertCls} role="alert">
              {errorMessage}
            </div>
          )}
          {!isActiveUser && (
            <>
              <div className="tw-mb-4">
                <label htmlFor="inquiryFormName" className={labelCls}>
                  Name <span className="tw-text-[#dc3545]"> (*)</span>
                </label>
                <input
                  type="email"
                  className={inputCls}
                  id="inquiryFormName"
                  onChange={(e) => {
                    setCustomerName(e.target.value);
                  }}
                  defaultValue={customerName}
                />
              </div>
              <div className="tw-mb-4">
                <label htmlFor="inquiryFormEmail" className={labelCls}>
                  Email address <span className="tw-text-[#dc3545]"> (*)</span>
                </label>
                <input
                  type="email"
                  className={inputCls}
                  id="inquiryFormEmail"
                  required
                  onChange={(e) => {
                    setCustomerEmail(e.target.value);
                  }}
                  defaultValue={customerEmail}
                />
              </div>
              <div className="tw-mb-4">
                <label htmlFor="inquiryFormPhone" className={labelCls}>
                  Phone <small>(Optional)</small>
                </label>
                <div className="tw-grid tw-grid-cols-1 sm:tw-grid-cols-2 tw-gap-2">
                  <Select
                    instanceId="inquiry-modal-phone-code"
                    options={phoneOptions}
                    value={
                      phoneOptions.find((o) => o.value === customerPhoneCodeId) ??
                      null
                    }
                    onChange={(opt: any) =>
                      setCustomerPhoneCodeId(opt ? opt.value : null)
                    }
                    placeholder="Country code"
                    aria-label="Country code"
                    isClearable
                    styles={phoneSelectStyles}
                    menuPlacement="auto"
                    menuPortalTarget={
                      typeof document !== "undefined" ? document.body : undefined
                    }
                    noOptionsMessage={() => "No match"}
                  />
                  <input
                    type="text"
                    inputMode="numeric"
                    pattern="[0-9]*"
                    className={inputCls}
                    placeholder="Phone Number"
                    id="inquiryFormPhone"
                    onChange={(e) => {
                      const value = e.target.value.replace(/\D/g, "");
                      setCustomerPhoneNumber(value);
                    }}
                    value={customerPhoneNumber}
                  />
                </div>
              </div>
            </>
          )}
          <div className="tw-mb-4">
            <label htmlFor="inquiryFormEmailQuestion" className={labelCls}>
              Your Question <span className="tw-text-[#dc3545]"> (*)</span>
            </label>
            <textarea
              className={inputCls}
              id="inquiryFormEmailQuestion"
              rows={5}
              onChange={(e) => {
                setQuestion(e.target.value);
              }}
              defaultValue={question}
            ></textarea>
          </div>
          <div className="tw-mb-4">
            <ReCAPTCHA
              sitekey="6LesOOIpAAAAAE1l4Z8q_ZVqpAGTnNaTRJTDzYxu"
              onChange={(e) => {
                setGoogleRecaptcha(e);
              }}
              asyncScriptOnLoad={() => {
                setGoogleRecaptcha(null);
              }}
              hl="en"
            />
          </div>
        </>
      )}
      {messageSendLoading && (
        <div className="tw-text-center tw-py-4">
          <span
            className={`${spinnerCls} tw-text-[#854ec9] tw-h-8 tw-w-8`}
            role="status"
          ></span>
          <p className="tw-mt-3">Your message is being sent. Please wait.</p>
        </div>
      )}
    </Modal>
  );
}
