"use client";
import { useState } from "react";
import styles from "./styles.module.scss";
import AccordionItem from "./accordion";

export default function Itineraries({ tourData }: { tourData: any }) {
  // Single-open accordion: opening one day closes the others.
  // First day is always open on page load.
  const [openId, setOpenId] = useState<any>(
    tourData.itineraries[0]?.id ?? null
  );

  function convertHeadingsToParagraphs(html: string) {
    return html.replace(
      /<h([1-6])[^>]*>([\s\S]*?)<\/h\1>/gi,
      (match, level, content) => `<p class="h${level}">${content}</p>`
    );
  }

  return (
    <>
      {tourData.itineraries.length > 0 && (
        <div className="tw-my-6" id="itinerary">
          <h2 className="tw-font-display tw-text-[22px] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-pb-1">
            Itinerary
          </h2>
          <div>
            {tourData.itineraries.map((item: any) => (
              <AccordionItem
                key={item.id}
                open={openId === item.id}
                onToggle={() =>
                  setOpenId(openId === item.id ? null : item.id)
                }
                header={
                  <span>
                    <span className="tw-font-semibold">Day {item.day}:</span>{" "}
                    {item.title}
                  </span>
                }
              >
                <div
                  className={styles["itinerary-description"]}
                  dangerouslySetInnerHTML={{
                    __html: item.description
                      ? convertHeadingsToParagraphs(item.description)
                      : "",
                  }}
                ></div>
              </AccordionItem>
            ))}
          </div>
        </div>
      )}
    </>
  );
}
