import Image from "next/image";
export default function IncludesTypes({
  tourData,
  item,
}: {
  tourData: any;
  item: any;
}) {
  const chipClass =
    "tw-inline-flex tw-items-center tw-gap-1.5 tw-rounded-full tw-border tw-border-solid tw-border-[#ebe7f0] tw-bg-white tw-m-1 tw-px-3 tw-py-1.5 tw-text-[13px] tw-font-medium tw-text-[#14101c]";
  return (
    <>
      {item.types?.map((type: any) => (
        <span key={type.id} className={chipClass}>
          {item.sid == "meals" && (
            <>
              <Image
                src={"/images/food-icons/" + type.sid + ".png"}
                width={25}
                height={25}
                alt=""
              />{" "}
            </>
          )}
          {type.name.en}
        </span>
      ))}
      {item.sid == "guide" && tourData.guide_type.name && (
        <p>
          <strong>Guiding Method</strong>
          <br />
          {tourData.guide_type.name.en}
        </p>
      )}
      {item.sid == "guide" &&
        tourData.languages.map((language: any) => (
          <span key={language.id} className={chipClass}>
            <Image
              src={"/images/flags/languages/" + language.id + ".svg"}
              width={30}
              height={20}
              alt=""
            />{" "}
            {language.name}
          </span>
        ))}
    </>
  );
}
