"use client";
import { memo, useRef, useState } from "react";
import Image from "next/image";
import cdnImage from "@/helpers/cdnImage";

// Native scroll-snap carousel (no Swiper, no Image `fill`). Slides are mounted
// lazily: only the first image loads on open; the rest load as you swipe to
// them (the next one is pre-warmed for a smooth slide).
const GalleryMobil = ({
  images,
  onLightBoxIndexChange,
  tourName,
}: {
  images: any;
  onLightBoxIndexChange: any;
  tourName: any;
}) => {
  const [active, setActive] = useState(0);
  const [loaded, setLoaded] = useState<number[]>([0]);
  const trackRef = useRef<HTMLDivElement>(null);

  if (!images || images.length === 0) return null;

  const onScroll = () => {
    const el = trackRef.current;
    if (!el || el.clientWidth === 0) return;
    const idx = Math.round(el.scrollLeft / el.clientWidth);
    setActive(idx);
    // Mount the reached slide (+ the next one) so it loads as you swipe.
    setLoaded((prev) =>
      prev.includes(idx) ? prev : [...prev, idx, idx + 1]
    );
  };

  return (
    <div className="tw-my-4 lg:tw-hidden">
      <div className="tw-relative tw-overflow-hidden tw-rounded-xl">
        <div
          ref={trackRef}
          onScroll={onScroll}
          className="tw-flex tw-overflow-x-auto [scrollbar-width:none] [&::-webkit-scrollbar]:tw-hidden"
          style={{
            scrollSnapType: "x mandatory",
            WebkitOverflowScrolling: "touch",
          }}
        >
          {images.map((item: any, i: number) => (
            <div
              key={i}
              className="tw-w-full tw-flex-none"
              style={{ scrollSnapAlign: "center" }}
            >
              {loaded.includes(i) ? (
                <Image
                  src={cdnImage(item.imageUrl)}
                  alt={`${tourName} ${i + 1}`}
                  width={900}
                  height={540}
                  quality={90}
                  priority={i === 0}
                  onClick={() => onLightBoxIndexChange(i)}
                  className="tw-block tw-w-full tw-h-[240px] tw-object-cover tw-cursor-pointer"
                />
              ) : (
                <div className="tw-w-full tw-h-[240px] tw-bg-[#f3f1f7] tw-animate-pulse" />
              )}
            </div>
          ))}
        </div>

        {images.length > 1 && (
          <div className="tw-absolute tw-bottom-2 tw-left-1/2 tw--translate-x-1/2 tw-flex tw-gap-1.5">
            {images.map((_: any, i: number) => (
              <span
                key={i}
                className={`tw-h-1.5 tw-rounded-full tw-transition-all tw-duration-200 ${
                  i === active ? "tw-w-4 tw-bg-white" : "tw-w-1.5 tw-bg-white/70"
                }`}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default memo(GalleryMobil);
