"use client";
import { createContext, useContext, useState, ReactNode } from "react";
import InquiryModal from "./inquiry-modal";
import DownloadBrochureModal from "./download-brochure-modal";
import MapModal from "./map-modal";

type TourModalsCtx = {
  openInquiry: () => void;
  openBrochure: () => void;
  openMap: (detail: any) => void;
};

const Ctx = createContext<TourModalsCtx | null>(null);

export function useTourModals() {
  const ctx = useContext(Ctx);
  if (!ctx) {
    throw new Error("useTourModals must be used within <TourModalsProvider>");
  }
  return ctx;
}

/**
 * Holds the open-state for the page's shared modals (inquiry, brochure, map)
 * that used to be triggered from many descendants via Bootstrap's
 * data-bs-target. Renders the three modals once and exposes openers via context.
 */
export function TourModalsProvider({
  tourId,
  tourSlug,
  children,
}: {
  tourId: number;
  tourSlug: string;
  children: ReactNode;
}) {
  const [inquiryOpen, setInquiryOpen] = useState(false);
  const [brochureOpen, setBrochureOpen] = useState(false);
  const [mapOpen, setMapOpen] = useState(false);
  const [mapDetail, setMapDetail] = useState<any>({});

  return (
    <Ctx.Provider
      value={{
        openInquiry: () => setInquiryOpen(true),
        openBrochure: () => setBrochureOpen(true),
        openMap: (detail: any) => {
          setMapDetail(detail);
          setMapOpen(true);
        },
      }}
    >
      {children}
      <InquiryModal
        tourId={tourId}
        open={inquiryOpen}
        onClose={() => setInquiryOpen(false)}
      />
      <DownloadBrochureModal
        tourSlug={tourSlug}
        open={brochureOpen}
        onClose={() => setBrochureOpen(false)}
      />
      <MapModal
        open={mapOpen}
        onClose={() => setMapOpen(false)}
        detail={mapDetail}
      />
    </Ctx.Provider>
  );
}
