"use client";
import { useState } from "react";
import styles from "./styles.module.scss";
import AccordionItem from "./accordion";

import IncludesTypes from "./includes-types";
export default function Includes({ tourData }: { tourData: any }) {
  // Single-open per column: opening one item closes the others in that column.
  const [openIncludedId, setOpenIncludedId] = useState<any>(null);
  const [openExcludedId, setOpenExcludedId] = useState<any>(null);
  return (
    <div className="attractions tw-my-4 tw-rounded-xl" id="includes">
      <h2 className="tw-font-display tw-text-[22px] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-pb-0 tw-mt-2">
        Trip includes
      </h2>

      {tourData.included.length > 0 && tourData.excluded.length > 0 && (
        <div className="tw-grid md:tw-grid-cols-2 tw-gap-x-6">
          <div>
            <div className="tw-my-4">
              <h3 className="tw-text-[18px] tw-font-semibold tw-text-[#14101c] tw-px-1 tw-pt-2 tw-pb-2">
                Included
              </h3>
              <div>
                {tourData.included.map((item: any) => {
                  if (item.pivot?.included == "hide") return null;
                  if (item.sid == "hygiene-protocol") item.name = "Good to Know";

                  return (
                    <AccordionItem
                      key={item.id}
                      open={openIncludedId === item.id}
                      onToggle={() =>
                        setOpenIncludedId(
                          openIncludedId === item.id ? null : item.id
                        )
                      }
                      header={
                        <>
                          <svg
                            xmlns="http://www.w3.org/2000/svg"
                            width="18"
                            height="18"
                            fill="currentColor"
                            className="tw-shrink-0 tw-text-[#198754]"
                            viewBox="0 0 16 16"
                          >
                            <path d="M8 15A7 7 0 1 1 8 1a7 7 0 0 1 0 14zm0 1A8 8 0 1 0 8 0a8 8 0 0 0 0 16z" />
                            <path d="M10.97 4.97a.235.235 0 0 0-.02.022L7.477 9.417 5.384 7.323a.75.75 0 0 0-1.06 1.06L6.97 11.03a.75.75 0 0 0 1.079-.02l3.992-4.99a.75.75 0 0 0-1.071-1.05z" />
                          </svg>
                          {item.name}
                        </>
                      }
                    >
                      <div className={styles["include-description"]}>
                        <div
                          dangerouslySetInnerHTML={{
                            __html: item.description ? item.description : "",
                          }}
                        ></div>
                        <IncludesTypes tourData={tourData} item={item} />
                      </div>
                    </AccordionItem>
                  );
                })}
              </div>
            </div>
          </div>
          <div>
            <div className="tw-my-4">
              <h3 className="tw-text-[18px] tw-font-semibold tw-text-[#14101c] tw-px-1 tw-pt-2 tw-pb-2">
                Excluded
              </h3>
              <div>
                {tourData.excluded.map((item: any) => {
                  if (item.pivot?.included == "hide") return null;
                  if (item.sid == "hygiene-protocol") item.name = "Good to Know";

                  return (
                    <AccordionItem
                      key={item.id}
                      open={openExcludedId === item.id}
                      onToggle={() =>
                        setOpenExcludedId(
                          openExcludedId === item.id ? null : item.id
                        )
                      }
                      header={
                        <>
                          <svg
                            xmlns="http://www.w3.org/2000/svg"
                            width="18"
                            height="18"
                            fill="currentColor"
                            className="tw-shrink-0 tw-text-[#dc3545]"
                            viewBox="0 0 16 16"
                          >
                            <path d="M8 15A7 7 0 1 1 8 1a7 7 0 0 1 0 14zm0 1A8 8 0 1 0 8 0a8 8 0 0 0 0 16z" />
                            <path d="M4.646 4.646a.5.5 0 0 1 .708 0L8 7.293l2.646-2.647a.5.5 0 0 1 .708.708L8.707 8l2.647 2.646a.5.5 0 0 1-.708.708L8 8.707l-2.646 2.647a.5.5 0 0 1-.708-.708L7.293 8 4.646 5.354a.5.5 0 0 1 0-.708z" />
                          </svg>
                          {item.name}
                        </>
                      }
                    >
                      <div className={styles["include-description"]}>
                        <div
                          dangerouslySetInnerHTML={{
                            __html: item.description ? item.description : "",
                          }}
                        ></div>
                        <IncludesTypes tourData={tourData} item={item} />
                      </div>
                    </AccordionItem>
                  );
                })}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
